package vn.iotstar.controller; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.PageRequest; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import vn.iotstar.repository.UserRepository; @Controller @RequiredArgsConstructor public class UserController{final UserRepository users;@GetMapping("/users")String list(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int page,Model m){m.addAttribute("users",users.findByUsernameContainingIgnoreCaseOrEmailContainingIgnoreCaseOrFullNameContainingIgnoreCase(q,q,q,PageRequest.of(Math.max(0,page),10)));m.addAttribute("q",q);return "users/list";}@PostMapping("/users/{id}/toggle")String toggle(@PathVariable Long id){var u=users.findById(id).orElseThrow();u.setEnabled(!u.isEnabled());users.save(u);return "redirect:/users";}}
